    public static void main(String[] args) {
        try {
            DirectoryNode root = new DirectoryNode();
            DirectoryNode usr = root.add("usr");
            usr.add("bin");
            usr.add("local/bin");
            usr.add("local/lib");
            root.add("opt/local");
